const tonZiehen=(c,x)=>x>=0?[c[0]+(255-c[0])*x, c[1]+(255-c[1])*x, c[2]+(255-c[2])*x]:[c[0]*(1+x), c[1]*(1+x), c[2]*(1+x)];
