  if(Math.abs(t)>1e-6||Math.abs(ft)>1e-6){ const cm=document.createElementNS(ns,'feColorMatrix'); cm.setAttribute('type','matrix');
    cm.setAttribute('values',[1+0.18*t+0.06*ft,0,0,0,0, 0,1-0.12*ft,0,0,0, 0,0,1-0.18*t+0.06*ft,0,0, 0,0,0,1,0].map(x=>x.toFixed(4)).join(' ')); f.appendChild(cm); }
