const mk=()=>document.createElement('canvas');
let oa=mk(),ob=mk(),oc=mk(),ores=mk(),okc=mk(),ovb=mk(),olicht=mk(),oherk=mk(); let VORB=vorbNeu();
let ca=oa.getContext('2d'),cb=ob.getContext('2d'),cc=oc.getContext('2d'),cres=ores.getContext('2d'),ckc=okc.getContext('2d'),clicht=olicht.getContext('2d'),cherk=oherk.getContext('2d');
function groesse(){ const f=$('#tbs-feld').getBoundingClientRect(), [bw,bh]=(bereit?qMass(bild):[1200,1200]), sc=Math.min(f.width/bw,f.height/bh);
  const W=Math.max(1,Math.round(bw*sc)), H=Math.max(1,Math.round(bh*sc));
  [lein,oa,ob,oc,ores,okc,ovb,olicht,oherk].forEach(c=>{ c.width=W; c.height=H; }); }

/* ---- LOOP-MODUS (Caspar_D, 10.09.2026: "als seemless loop waere schon schoen, gerade bei Schneefall,
   Feuer, Funkenflug"): fuer den Videoexport wird jede Geschwindigkeit auf ein ganzes Vielfaches von
   1/Cliplaenge eingerastet. Dann steht nach L Sekunden jede Flocke, jede Flamme und jeder Streifen
   wieder genau am Anfang - ein echter Loop, kein Ueberblenden. LOOP=0 heisst: normaler Betrieb, nichts rastet ein.
   UNSICHTBAR IST DAS NICHT IMMER (Befund 14.09.2026): der Clip ist 5 bis 10 s lang, das Raster also
   0,1 bis 0,2 Umlaeufe je Sekunde grob. Eine Rate von 0,05 wird 0,1, eine Periode von 40 s wird 10 s -
   bis zu fuenfzig Prozent, nicht "hoechstens ein Prozent", wie hier vorher stand. Darum gilt:
   Vorzeichen bleibt (Wind nach links fliegt auch im Export nach links), 0 bleibt 0 (Stillstand ist
   ein gueltiger Loop), und nur eine Schwingung, die ueberhaupt schwingt, bekommt mindestens einen
   ganzen Umlauf - sonst stuende ein Flackern im Export still. Nicht endliche Werte gehen unveraendert
   durch; ein Aufrufer, der NaN hineingibt, bekommt es wie in der Vorschau zurueck. */
let LOOP=0;
const lpR = r => (LOOP>0 && r!==0 && Math.abs(r)<Infinity) ? Math.sign(r)*Math.max(1,Math.round(Math.abs(r)*LOOP))/LOOP : r;   /* Rate: Umlaeufe je Sekunde */
const lpP = p => (LOOP>0 && p!==0 && Math.abs(p)<Infinity) ? Math.sign(p)*LOOP/Math.max(1,Math.round(LOOP/Math.max(1e-3,Math.abs(p)))) : p;   /* Periode in Sekunden; Infinity = steht */
const lpW = w => LOOP>0 ? 2*Math.PI*lpR(w/(2*Math.PI)) : w;                            /* Kreisfrequenz im Sinus */
/* Umbruch-Geschwindigkeit (bricht bei `weite` um): ganze Umlaeufe OHNE Mindestens-einen. Eine Flocke,
   die in der Vorschau in 10 s ein Achtel Bild faellt, stand vorher im Export auf einem ganzen Bild je
   Clip - achtmal zu schnell. Jetzt rundet sie auf 0 und steht. Ob das besser ist als zu rasen, kann
   nur der Maler entscheiden; dafuer sagt lpVUmlauf, wie weit die Rundung daneben liegt. */
const lpV = (v,weite) => (LOOP>0 && v!==0 && Math.abs(v)<Infinity && weite>0) ? Math.sign(v)*Math.round(Math.abs(v)*LOOP/weite)*weite/LOOP : v;
/* Auskunft zu lpV: m = ganze Umlaeufe je Clip (mit Vorzeichen), echt = die ungerundete Zahl,
   verhaeltnis = m/echt (1 = unverfaelscht, 0 = steht still statt zu wandern, 2 = doppelt so schnell).
   Ausserhalb des Loops und bei v=0 ist nichts verfaelscht: verhaeltnis 1. Ein Partikel, dessen
   verhaeltnis weit von 1 liegt, kann auf Lebensdauer-Betrieb gehen, statt umzubrechen. */
/* PENDELN STATT RASEN (Gegenpruefung 15.09.2026). Eine Bahn, die in der Vorschau keinen ganzen Umlauf je Clip
   schafft - der wandernde Scheinwerfer bei Tempo 16 kommt in 9,5 s auf 0,59, der Laser-Ursprung bei Tempo 8 auf
   0,3 -, bekam von lpR einen ganzen: 1,7- bis 4,2-mal so schnell wie im Pult. Stillstand waere ebenso falsch, die
   Bahn wandert ja. Also pendelt sie im Export auf ihrem Bahnstueck hin und zurueck: Phase ph+A*sin(2*pi*t/L),
   A so, dass die mittlere Phasengeschwindigkeit 4A/L die der Vorschau (2*pi*f) trifft, also A=pi*f*L/2. Das
   schliesst nach L wie ein Umlauf und haelt das Tempo. Ab einem Umlauf je Clip rastet lpR wie bisher. Die
   Vorschau rechnet an der Aufrufstelle ihren eigenen Ausdruck, hier kommt sie nur der Vollstaendigkeit halber an. */
function lpBahn(f,t,ph){ if(!(LOOP>0) || f===0 || !(Math.abs(f)<Infinity)) return 2*Math.PI*f*t+ph;
  const echt=Math.abs(f)*LOOP; return echt>=1 ? 2*Math.PI*lpR(f)*t+ph : ph+Math.sign(f)*Math.PI*echt/2*Math.sin(2*Math.PI*t/LOOP); }
