                u=0.5+0.5*Math.sin(2*Math.PI*ph);   /* der Spiegel schwingt, er faehrt nicht gleichmaessig */
          if(aus>0){ const seg=Math.floor(ph*stuf*2); if(hs(seg*3+e.id)<aus) continue; }
          const wert=dicht*(1-0.85*k/M), b0=Math.floor(u*NB)-(spann>>1);
