        cx.save(); cx.globalAlpha=al; cx.translate(x,y); cx.rotate(Math.sin(lpW(0.9)*t+i*1.3)*0.32);
        cx.fillStyle=farbeVon(i,a,0.45*(1-oe)*(1-oe));
        for(const sg of [-1,1]){ cx.save(); cx.scale(sg*oe,1);
          cx.beginPath(); cx.moveTo(0,-sz*0.22); cx.bezierCurveTo(sz*0.30,-sz*1.30, sz*1.40,-sz*1.00, sz*1.02,-sz*0.08); cx.bezierCurveTo(sz*0.90,sz*0.12, sz*0.40,sz*0.08, 0,-sz*0.02); cx.fill();
          cx.beginPath(); cx.moveTo(0,sz*0.02); cx.bezierCurveTo(sz*0.62,sz*0.06, sz*0.98,sz*0.55, sz*0.58,sz*0.98); cx.bezierCurveTo(sz*0.28,sz*1.16, sz*0.04,sz*0.68, 0,sz*0.10); cx.fill();
          cx.restore(); }
        const ws=Math.max(0.5*U,sz*0.15), lw=Math.max(0.5,ws); cx.fillStyle=farbeVon(i,a*0.85*(ws/lw));   /* nur die Breite des Koerpers ist geklemmt, also einfach ws/lw */
        cx.beginPath(); cx.ellipse(0,sz*0.06,lw,sz*0.66,0,0,7); cx.fill();
