        const tm=lpW(1.05+hs(i+4800)*1.5)*t+i*2.7, sx=Math.abs(Math.cos(tm)), dr=lpW(0.35+hs(i+4900)*0.5)*t+i*1.3;
        const bs=Math.max(0.4*U,sz*1.15*Math.max(0.07,sx)), bw=Math.max(0.4,bs), bh=Math.max(0.4,sz*0.8), rd=Math.min(bw,bh)*0.3;
        cx.save(); cx.globalAlpha=al*(bs/bw); cx.translate(x,y); cx.rotate(dr);
        cx.fillStyle=farbeVon(i,a,0.55*(1-sx)*(1-sx));
