    if(typeof T.hinweis==='function'){ let hw=null; try{ hw=T.hinweis(e); }catch(x){ hw=null; } if(hw) h+='<div class="tbs-fehltlicht">'+hw+'</div>'; }
    /* Regler: erst die eigenen, dann hinter einer feinen Linie das Bekannte in fester Reihenfolge - Antrieb, Atem, Invertieren, Verrechnung, Staerke. */
