  x.fillStyle=s; x.save(); x.translate(kx+r*0.15,ky+r*1.08); x.scale(1,0.28); x.beginPath(); x.arc(0,0,r*1.1,0,7); x.fill(); x.restore();
  let g=x.createRadialGradient(kx-r*0.38,ky-r*0.42,r*0.04,kx,ky,r); g.addColorStop(0,'#f5f5f5'); g.addColorStop(0.35,'#b9b9bb'); g.addColorStop(0.7,'#5a5a5e'); g.addColorStop(0.92,'#232326'); g.addColorStop(1,'#1a1a1d');
