    if(sitzt<ZUFALL_BODEN) return ' · keine Länge bleibt über das Lied im Takt – die Pulse laufen im Suno-Video gegen die Musik'+(warum?' — '+warum:'');   /* Caspar_D, 15.09.2026 */
