    { const b=$('#tbs-mSelbst'); if(b) b.classList.toggle('an',!(SCHLEIFE.schlaege>0)); const z=$('#tbs-mZahl'); if(z) z.textContent=(lg&&lg.M)?String(lg.M):'–'; }
