      for(let k=0;k<=n;k++){ const tau=Math.min(L-1e-6,L*k/n), q=schleifeZeitRoh(tau,L,Dv,lg); pt.push([X(tau),y1-(y1-y0)*Math.max(0,Math.min(1,q.s/Dv))]); }
